const EX_DATA={"Barbell Bench Press":{gif:"barbell-bench-press",primary:["Pectoralis Major"],secondary:["Triceps","Anterior Deltoid"],about:"The cornerstone upper-body strength lift. Builds chest, front delts and triceps while teaching full-body bracing under load."},"Incline Dumbbell Press":{gif:"incline-dumbbell-press",primary:["Upper Pectorals"],secondary:["Anterior Deltoid","Triceps"],about:"Targets the often-lagging upper chest. Dumbbells allow a deeper stretch and even left-right development."},"Cable Chest Fly":{gif:"cable-chest-fly",primary:["Pectoralis Major"],secondary:["Anterior Deltoid"],about:"Constant cable tension isolates the chest through a long arc \u2014 ideal for the squeeze and inner-chest detail."},"Seated DB Shoulder Press":{gif:"seated-db-shoulder-press",primary:["Anterior Deltoid","Lateral Deltoid"],secondary:["Triceps","Upper Pectorals"],about:"Primary mass-builder for the shoulders. Seated and braced keeps the focus on the delts, not momentum."},"Lateral Raises":{gif:"lateral-raises",primary:["Lateral Deltoid"],secondary:["Trapezius"],about:"The key to wider, capped shoulders. Light weight, strict form and slow negatives beat heavy swinging every time."},"Tricep Rope Pushdown":{gif:"tricep-rope-pushdown",primary:["Triceps"],secondary:["Forearms"],about:"A staple triceps isolation. Flaring the rope at the bottom maximises the contraction on all three heads."},"Overhead DB Tricep Ext.":{gif:"overhead-db-tricep-ext",primary:["Triceps (Long Head)"],secondary:[],about:"The overhead position stretches the long head of the triceps under load \u2014 crucial for overall arm thickness."},"Barbell Deadlift":{gif:"barbell-deadlift",primary:["Glutes","Hamstrings","Erector Spinae"],secondary:["Lats","Trapezius","Forearms","Quads"],about:"The ultimate full-body strength builder. Trains the entire posterior chain and grip while reinforcing a braced, neutral spine."},"Lat Pulldown":{gif:"lat-pulldown",primary:["Latissimus Dorsi"],secondary:["Biceps","Rear Deltoid"],about:"Builds the V-taper. Driving the elbows down and back recruits the lats far better than just pulling with the arms."},"Seated Cable Row":{gif:"seated-cable-row",primary:["Latissimus Dorsi","Rhomboids"],secondary:["Biceps","Rear Deltoid"],about:"A complete mid-back builder. Squeezing the shoulder blades at the end develops thickness and posture."},"Single-Arm DB Row":{gif:"single-arm-db-row",primary:["Latissimus Dorsi","Rhomboids"],secondary:["Biceps","Rear Deltoid"],about:"Unilateral rowing irons out left-right imbalances and allows a bigger range of motion than barbell rows."},"Barbell Curl":{gif:"barbell-curl",primary:["Biceps Brachii"],secondary:["Forearms"],about:"The classic biceps mass-builder. Strict form and a controlled negative are what drive the growth."},"Hammer Curl":{gif:"hammer-curl",primary:["Brachialis","Biceps"],secondary:["Forearms"],about:"The neutral grip hits the brachialis underneath the biceps and the forearms \u2014 adds width and thickness to the arm."},"Barbell Back Squat":{gif:"barbell-back-squat",primary:["Quadriceps","Glutes"],secondary:["Hamstrings","Core","Erector Spinae"],about:"The king of leg exercises. Builds total lower-body strength and size while heavily taxing the core and back."},"Romanian Deadlift DB":{gif:"romanian-deadlift-db",primary:["Hamstrings","Glutes"],secondary:["Erector Spinae","Forearms"],about:"A hip-hinge that loads the hamstrings in their stretched position \u2014 the best hamstring and glute developer."},"Leg Press Machine":{gif:"leg-press-machine",primary:["Quadriceps","Glutes"],secondary:["Hamstrings"],about:"Lets you overload the legs safely without spinal loading. Foot placement shifts emphasis between quads and glutes."},"Leg Curl Machine":{gif:"leg-curl-machine",primary:["Hamstrings"],secondary:["Calves"],about:"Isolates the hamstrings through knee flexion \u2014 the perfect complement to hip-hinge movements for complete leg development."},"Walking Lunges":{gif:"walking-lunges",primary:["Quadriceps","Glutes"],secondary:["Hamstrings","Calves"],about:"A unilateral leg builder that also trains balance and stability. Big stretch on the glutes with every step."},"Standing Calf Raises":{gif:"standing-calf-raises",primary:["Gastrocnemius"],secondary:["Soleus"],about:"Trains the larger calf muscle. A full stretch at the bottom and a pause at the top under high reps is the key to stubborn calves."},"Hanging Knee Raises":{gif:"hanging-knee-raises",primary:["Lower Abs","Hip Flexors"],secondary:["Obliques","Forearms"],about:"One of the best lower-ab movements. Curling the pelvis up (not just lifting the knees) is what hits the abs hardest."},"Cable Crunch":{gif:"cable-crunch",primary:["Rectus Abdominis"],secondary:["Obliques"],about:"Weighted ab training for real growth. Crunching down with the abs \u2014 not pulling with the arms \u2014 is essential."},"Decline Sit-ups":{gif:"decline-situps",primary:["Rectus Abdominis"],secondary:["Hip Flexors"],about:"The decline angle increases the range and load on the abs versus flat sit-ups. Control the descent for max tension."},"Russian Twists weighted":{gif:"russian-twists",primary:["Obliques"],secondary:["Rectus Abdominis"],about:"Rotational core work that builds the obliques. Rotate the torso, not just the arms, for it to count."},"Plank Hold":{gif:"plank-hold",primary:["Core / Transverse Abdominis"],secondary:["Shoulders","Glutes"],about:"An isometric that builds deep core stability and anti-extension strength \u2014 the foundation for all heavy lifting."},"Ab Wheel Rollout":{gif:"ab-wheel-rollout",primary:["Rectus Abdominis","Core"],secondary:["Lats","Shoulders"],about:"One of the most demanding ab exercises. Bracing hard to keep the spine from arching is what makes it so effective."},"Mountain Climbers":{gif:"mountain-climbers",primary:["Core","Hip Flexors"],secondary:["Shoulders","Quads"],about:"A cardio-core hybrid. Keeping the hips low and steady turns it into serious anti-rotation core work."},Burpees:{gif:"burpees",primary:["Full Body"],secondary:["Chest","Quads","Core"],about:"A full-body conditioning movement that spikes the heart rate fast. Excellent for fat loss and work capacity."},"DB Thrusters squat+press":{gif:"db-thrusters",primary:["Quadriceps","Glutes","Shoulders"],secondary:["Triceps","Core"],about:"A squat-to-press combo that trains the whole body in one explosive movement \u2014 huge metabolic and strength stimulus."},"Face Pulls":{gif:"face-pulls",primary:["Rear Deltoid","Trapezius"],secondary:["Rotator Cuff"],about:"The best insurance for healthy shoulders. Strengthens the rear delts and upper back to balance all the pressing."},"Treadmill Incline 5 Speed 5.5":{gif:"treadmill",primary:["Quadriceps","Hamstrings"],secondary:["Glutes","Calves","Cardiovascular System"],about:"Incline running raises the heart rate for fat loss while sparing the joints. The incline shifts more of the work onto the glutes and hamstrings."},"Treadmill Incline Walk":{gif:"treadmill",primary:["Glutes","Hamstrings"],secondary:["Quadriceps","Calves","Cardiovascular System"],about:"Brisk incline walking is sustainable, low-impact cardio that burns serious calories while emphasising the glutes and hamstrings."},"Cross Trainer Resistance 7":{gif:"elliptical-machine",primary:["Quadriceps","Hamstrings"],secondary:["Glutes","Calves","Cardiovascular System"],about:"A low-impact full-body cardio machine. The gliding motion burns calories with minimal joint stress, and pushing the handles adds upper-body work."},"Cross Trainer Steady State":{gif:"elliptical-machine",primary:["Quadriceps","Hamstrings"],secondary:["Glutes","Calves","Cardiovascular System"],about:"Sustained moderate-pace elliptical work builds an aerobic base and burns fat with almost no impact on the knees or hips."},"Cycling Sprint HIIT":{gif:"stationary-bike",primary:["Quadriceps","Glutes"],secondary:["Hamstrings","Calves","Cardiovascular System"],about:"Short all-out sprints with easy recovery spike the heart rate and keep burning calories long after the session \u2014 the most time-efficient fat-loss tool."},"Cycling HIIT":{gif:"stationary-bike",primary:["Quadriceps","Glutes"],secondary:["Hamstrings","Calves","Cardiovascular System"],about:"Interval cycling alternates hard sprints with easy spinning to build conditioning and maximise calorie burn with low joint impact."},"Battle Ropes or Jump Rope":{gif:"battle-rope",primary:["Shoulders","Core"],secondary:["Forearms","Cardiovascular System"],about:"Explosive conditioning that hammers the shoulders, arms and core while spiking the heart rate \u2014 superb for fat loss and work capacity."},"Plank to Push-up":{gif:"high-plank",primary:["Core","Chest"],secondary:["Shoulders","Triceps"],about:"Moving between forearm plank and push-up position trains the core to resist rotation while adding pressing work for the chest and triceps."}},FORM_CUES={"Treadmill Incline 5 Speed 5.5":["Set incline to 5 and speed to about 5.5","Stand tall \u2014 do not lean on the handrails","Drive through the whole foot with short, quick steps","Breathe rhythmically and hold a steady pace for 20 min"],"Treadmill Incline Walk":["Set incline to 6 and a brisk walking pace","Stand tall, let your arms swing naturally","Do not grip the rails \u2014 let your legs do the work","Keep your heart rate elevated for the full 25 min"],"Cross Trainer Resistance 7":["Set resistance to 7 and stand upright","Push and pull the handles with every stride","Drive through your heels, core braced","Hold a smooth, steady rhythm throughout"],"Cross Trainer Steady State":["Set resistance to 8 and settle into a steady pace","Keep posture upright and engage the handles","Breathe steadily \u2014 you should still be able to talk","Hold the same effort for 15 min"],"Cycling Sprint HIIT":["Warm up 2-3 min at an easy spin","Sprint all-out for 30 seconds","Spin easy for 90 seconds to recover","Repeat for 10 rounds, keeping your posture stable"],"Cycling HIIT":["Warm up a few minutes easy","Sprint hard for 30 seconds","Recover with easy spinning for 90 seconds","Repeat 12 rounds, core tight throughout"],"Battle Ropes or Jump Rope":["Athletic stance, knees soft, core braced","Drive powerful waves through the ropes (or skip light and fast)","Work hard for 30 seconds","Rest 30 seconds, then repeat for 3 rounds"],"Plank to Push-up":["Start in a forearm plank, body in a straight line","Press up onto one hand, then the other, into push-up position","Lower back down one forearm at a time","Keep hips level \u2014 do not rock side to side"],"Barbell Bench Press":["Lie flat, feet planted, arch lower back slightly","Grip slightly wider than shoulder width, wrists straight","Lower bar to lower chest, elbows at 45 degrees from torso","Press explosively up, do not shrug shoulders at top"],"Incline Dumbbell Press":["Set bench to 30-45 degrees, dumbbells at shoulder level","Keep chest up, squeeze shoulder blades together","Lower until elbows are slightly below bench","Press up and slightly inward, squeeze chest at top"],"Cable Chest Fly":["Stand between cables, slight forward lean","Keep a slight bend in elbows throughout","Bring hands together in a hugging arc","Squeeze chest hard at peak, control the return"],"Seated DB Shoulder Press":["Sit upright, core tight, feet flat","Start with dumbbells at ear level, palms forward","Press straight up, do not lock elbows at top","Lower slowly \u2014 2 seconds down"],"Lateral Raises":["Stand tall, slight bend at elbows","Raise arms to shoulder height only","Lead with elbows, not wrists","Lower slowly \u2014 this is where growth happens"],"Tricep Rope Pushdown":["Elbows pinned to sides throughout","Push rope down and flare wrists out at bottom","Squeeze triceps hard at bottom","Control the return \u2014 do not let it fly up"],"Overhead DB Tricep Ext.":["Hold dumbbell overhead with both hands","Elbows pointing forward, not flaring out","Lower behind head until forearms parallel floor","Press up to full extension, squeeze triceps"],"Barbell Deadlift":["Feet hip-width, bar over mid-foot","Grip just outside legs, spine neutral throughout","Push the floor away \u2014 do not pull with your back","Hips and shoulders rise at same rate off the floor","Lock out by squeezing glutes, not hyperextending back"],"Lat Pulldown":["Grip slightly wider than shoulder width, lean back 10 degrees","Pull bar to upper chest, lead with elbows","Squeeze lats at bottom \u2014 pause 1 second","Let bar rise slowly, feel the stretch at top"],"Seated Cable Row":["Sit tall, chest up, slight arch in lower back","Pull handle to lower sternum, elbows go back","Squeeze shoulder blades together at end","Return slowly \u2014 full stretch at front is key"],"Single-Arm DB Row":["Support with opposite hand and knee on bench","Keep spine neutral, parallel to floor","Pull dumbbell to hip, elbow travels straight back","Lower slowly, get a full shoulder stretch"],"Face Pulls":["Set cable at face height, use rope attachment","Pull rope to forehead, elbows above wrists","Rotate hands outward at end \u2014 thumbs back","Controls rear delts and rotator cuff health"],"Barbell Curl":["Stand tall, elbows pinned to sides","Curl bar up without swinging torso","Squeeze biceps hard at the top","Lower over 3 seconds \u2014 the negative builds muscle"],"Hammer Curl":["Neutral grip \u2014 palms facing each other","Curl with control, no swinging","Works brachialis and forearms more than regular curl","Alternate arms or do both simultaneously"],"Barbell Back Squat":["Bar on upper traps, feet shoulder width, toes out 15-30 degrees","Big breath and brace core before descending","Knees track over toes, sit between legs","Break parallel \u2014 crease of hip below top of knee","Drive up through heels, hips and chest rise together"],"Romanian Deadlift DB":["Hold dumbbells in front, slight knee bend","Hinge at hips \u2014 push hips BACK, not down","Feel the hamstring stretch, keep back flat","Drive hips forward to return, squeeze glutes at top"],"Leg Press Machine":["Feet shoulder width, mid-plate, toes slightly out","Lower until knees reach 90 degrees \u2014 no lower","Press through whole foot, do not lock knees","Never let lower back peel off the pad"],"Leg Curl Machine":["Lie face down, pad just above ankles","Curl heels toward glutes, full range","Squeeze hamstrings at top, lower slowly","Do not let hips rise off the pad"],"Walking Lunges":["Front knee over ankle, not past toes","Back knee lowers just above the floor","Keep torso upright, core engaged","Push off front foot to step forward"],"Standing Calf Raises":["Full range: deep stretch at bottom, full rise at top","Pause 1 second at peak contraction","Go slow \u2014 calves respond to time under tension","3 sets of 15-20 reps minimum"],"Hanging Knee Raises":["Hang from bar, shoulders packed down","Bring knees to chest by curling pelvis up","Do not swing \u2014 control the movement","Lower slowly to maximize core engagement"],"Cable Crunch":["Kneel at cable, rope at back of head","Crunch DOWN toward knees, not forward","Move from the abs \u2014 do not pull with arms","Round your back \u2014 correct form here"],"Decline Sit-ups":["Anchor feet, hands lightly behind head","Curl up through full range","Do not pull neck with your hands","Lower slowly \u2014 3 seconds down"],"Russian Twists weighted":["Sit at 45 degrees, feet slightly elevated","Rotate torso side to side, not just arms","Keep chest up, do not collapse forward","Add weight once bodyweight becomes easy"],"Plank Hold":["Forearms on floor, body straight as a board","Do not let hips sag or pike up","Breathe normally \u2014 squeeze abs and glutes","Build from 30s to 60s to 90s over weeks"],"Ab Wheel Rollout":["Start kneeling, wheel directly under shoulders","Roll forward keeping core braced \u2014 back must not arch","Go as far as you can control, then roll back","This is harder than it looks \u2014 start with small range"],"Mountain Climbers":["High plank position, hands under shoulders","Drive knees to chest alternately, stay level","Keep hips down, do not bounce them","Fast for cardio effect, slow for core strength"],"Cycling Sprint HIIT":["Resistance medium-high for sprints","30s all-out effort, 90s easy recovery \xD7 10 rounds","Keep cadence high during sprints \u2014 above 80 RPM","Burns 200-300 extra calories post-workout (EPOC effect)"],Burpees:["Squat down, jump feet back to plank","Do a push-up then jump feet back to hands","Explode upward, clap overhead at the top","Full extension at the top \u2014 every rep"],"DB Thrusters squat+press":["Hold dumbbells at shoulders, feet shoulder width","Squat to parallel, drive up explosively","Use the squat momentum to press overhead","One fluid movement \u2014 squat and press together"],"Plank to Push-up":["Start in forearm plank position","Push up to high plank one arm at a time","Lower back to forearm plank one arm at a time","Alternate which arm leads each rep"],"Battle Ropes / Jump Rope":["Battle rope: anchor low, stand with slight squat","Alternate waves \u2014 keep rhythm for full 30 seconds","Jump rope: light on feet, wrists do the turning","Both are excellent cardio and shoulder conditioning"],"Treadmill Incline 5 Speed 5.5":["Incline 5 increases calorie burn by ~50% vs flat","Hold steady pace, do not hold onto rails","Swing arms naturally, look forward not down","Target heart rate: 130-150 BPM for fat burn zone"],"Cross Trainer Resistance 7":["Use arm handles actively \u2014 do not just stand","Keep resistance high enough to feel challenged","Smooth circular motion, do not bounce","Great low-impact cardio \u2014 burns similar to running"]};